REF=/workspace/dataset/test11_executable
perl -e '
srand(7);
my @uni = ("日","é","😀","ü");
my $bad = 0; my $n = 0;
for my $i (1..120) {
  my $len = int(rand(300));
  my $s = "";
  for (1..$len) { $s .= (rand()<0.25) ? $uni[int(rand(@uni))] : chr(97+int(rand(26))); }
  $s = "xn--".$s if rand()<0.2;
  my $out = `$ENV{REF} "$s"`;
  # fields 5,6 are booleans; but empty fields break split on whitespace.
  # Instead recompute full expected line? Simpler: extract via known structure:
  # print s with markers. Use: run ref with the arg, compare 5th/6th whitespace token only if no spaces in s (s has none).
  my @f = split / /, $out;
  my $blen = length($s); # bytes (perl internal: utf8 flag off since we built from bytes)
  my $exp_vd = ($blen >= 1 && $blen <= 255) ? 1 : 0;
  my $exp_vl = ($blen >= 1 && $blen <= 63) ? 1 : 0;
  $n++;
  if ($f[4] != $exp_vd || $f[5] != $exp_vl) {
    $bad++;
    print "RULE VIOLATION: bytelen=$blen ref_vd=$f[4] ref_vl=$f[5] expected $exp_vd/$exp_vl\n";
  }
}
print "checked $n random inputs against byte-length rule: $bad violations\n";
'

REF=/workspace/dataset/test11_executable
perl -e '
srand(7); binmode(STDOUT);
my @uni = ("日","é","😀","ü");
for my $i (1..150) {
  my $len = int(rand(300));
  my $s = "";
  for (1..$len) { $s .= (rand()<0.25) ? $uni[int(rand(@uni))] : chr(97+int(rand(26))); }
  $s = "xn--".$s if rand()<0.2;
  print $s, "\0";
}' > /tmp/difftest/inputs.nul
viol=0; n=0
while IFS= read -r -d '' s; do
  n=$((n+1))
  out=$("$REF" "$s")
  vd=$(echo "$out" | awk '{print $5}'); vl=$(echo "$out" | awk '{print $6}')
  blen=$(printf '%s' "$s" | wc -c)
  evd=0; evl=0
  [ "$blen" -ge 1 ] && [ "$blen" -le 255 ] && evd=1
  [ "$blen" -ge 1 ] && [ "$blen" -le 63 ] && evl=1
  if [ "$vd" != "$evd" ] || [ "$vl" != "$evl" ]; then
    viol=$((viol+1)); echo "RULE VIOLATION bytelen=$blen ref=$vd/$vl expected=$evd/$evl"
  fi
done < /tmp/difftest/inputs.nul
echo "checked $n inputs against byte-length rule: $viol violations"
